304	        )
305	        .await
306	        .unwrap();
307	        sqlx::query(
308	            "INSERT INTO accounts (did, email, password_hash, created_at, updated_at) \
309	             VALUES ('did:plc:testaccount000000000000', 'test@example.com', NULL, \
310	             datetime('now'), datetime('now'))",
311	        )
312	        .execute(&state.db)
313	        .await
314	        .unwrap();
