64	        None => {
65	            return OAuthTokenError::new("invalid_dpop_proof", "DPoP header required")
66	                .into_response();
67	        }
68	    };
69	
70	    let token_url = format!(
71	        "{}/oauth/token",
72	        state.config.public_url.trim_end_matches('/')
73	    );
74	
75	    let jkt =
