78	        {
79	            Ok(jkt) => jkt,
80	            Err(DpopTokenEndpointError::MissingHeader) => {
81	                return OAuthTokenError::new("invalid_dpop_proof", "DPoP header required")
82	                    .into_response();
83	            }
84	            Err(DpopTokenEndpointError::InvalidProof(msg)) => {
